%[text] # Passive Acoustic Imaging Example
%[text] This example images sound sources that emit themselves, such as gas leaks, with `clait.calculatePassiveAcousticImage`. It compares conventional delay-and-sum (DAS) with the adaptive Capon (MVDR) beamformer and its robust version (RCB). See the passive acoustic image help page for the background.
%[text] ## Setup sensor and scene
%[text] Three leaks emit independent broadband noise between 20 and 80 kHz, at different strengths, in front of a 32 microphone array. Every microphone also records independent noise. 0.2 seconds is recorded.
structSensor = struct();
structSensor.sampleRate = 450e3;
structSensor.numSamplesSensor = 0.2 * structSensor.sampleRate;
structSensor.coordinatesMicrophones = [0 -0.0384 0.0151; 0 -0.0232 0.0101; 0 -0.0121 0.0164; 0 -0.0046 0.0153; ...
                                       0 -0.0367 0.0054; 0 -0.0144 0.0061; 0 0.0054 0.0011; 0 0.0273 -0.0027; ...
                                       0 -0.0387 0.0001; 0 -0.0281 0.0002; 0 -0.0094 -0.0013; 0 -0.0060 -0.0000; ...
                                       0 -0.0357 -0.0117; 0 -0.0318 -0.0112; 0 -0.0286 -0.0166; 0 0.0029 -0.0086; ...
                                       0 -0.0011 0.0178; 0 0.0067 0.0115; 0 0.0103 0.0144; 0 0.0172 0.0140; ...
                                       0 0.0384 0.0022; 0 0.0283 0.0162; 0 0.0354 0.0125; 0 0.0373 0.0150; ...
                                       0 -0.0084 -0.0047; 0 0.0107 -0.0111; 0 0.0189 -0.0166; 0 0.0363 -0.0101; ...
                                       0 0.0057 -0.0224; 0 -0.0036 -0.0223; 0 0.0315 -0.0161; 0 0.0083 -0.0178];

structScene = struct();
structScene.sourceAzimuth   = [0   -40   25];
structScene.sourceElevation = [0    20  -30];
structScene.sourceStrength  = [1   0.5  0.7];   % RMS, so 0, -6 and -3.1 dB
structScene.sourceBand = [20e3 80e3];
structScene.noiseLevel = 0.1;
dataMicrophones = clait.simulatePassiveMicrophoneData(structScene, structSensor);
%%
%[text] ## Setup imaging
%[text] Nearly uniform directions with 1 degree spacing within a 70 degree cone. The adaptive methods give very narrow peaks, so a fine direction grid is needed to see them. The cross-spectral matrix uses 512 sample snapshots with 50% overlap between 20 and 80 kHz.
structImage = struct();
[structImage.directionsAzimuth, structImage.directionsElevation] = ...
    clait.generateDirections('equalarea', struct('spacing', 1, 'coneAngle', 70));
structImage.frequencyRange = [20e3 80e3];
structImage.fftLength = 512;
structImage.fftOverlap = 0.5;
structImage.methodProcessing = 'mexcuda';   % Falls back to the CPU if no NVIDIA GPU is available
%%
%[text] ## Calculate the passive acoustic images
methods = {'DAS', 'MVDR', 'RCB'};
powerMaps = cell(size(methods));
for cntMethod = 1:numel(methods) %[output:group:77608f89]
    structImage.methodImaging = methods{cntMethod};
    tic;
    powerMaps{cntMethod} = clait.calculatePassiveAcousticImage(dataMicrophones, structSensor, structImage);
    fprintf('%-4s: %d directions in %.3f s\n', methods{cntMethod}, numel(structImage.directionsAzimuth), toc); %[output:99ad68f6]
end %[output:group:77608f89]
%%
%[text] ## Example 1: DAS, MVDR and RCB
%[text] The black circles mark the true source directions. DAS shows every source with the wide array beam and high sidelobes. MVDR gives very sharp peaks and a low background, but its source levels are wrong: the strongest source looks weakest, because MVDR suppresses a source as soon as no image direction lies exactly on it. RCB keeps the sharp, clean image of MVDR and gets the levels right (0, -6 and -3.1 dB).
figure('Position', [100 100 1500 460]); %[output:4af059e3]
tiledlayout(1, numel(methods), 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:4af059e3]
opts = clait.plotSphericalEnergyscape('options');
opts.valueType = 'power';
opts.dbCut = -30;
opts.labelStyle = 'graticule';
opts.showColorbar = false;

k = sqrt(2 ./ (1 + cosd(structScene.sourceElevation) .* cosd(structScene.sourceAzimuth))) / sqrt(2);
sourceX = -k .* cosd(structScene.sourceElevation) .* sind(structScene.sourceAzimuth);
sourceY = k .* sind(structScene.sourceElevation);
for cntMethod = 1:numel(methods)
    nexttile; %[output:4af059e3]
    opts.title = methods{cntMethod};
    opts.showColorbar = (cntMethod == numel(methods));
    [~, hCbar] = clait.plotSphericalEnergyscape(powerMaps{cntMethod}, structSensor, structImage, opts);
    hold on;
    plot(sourceX, sourceY, 'ko', 'MarkerSize', 14, 'LineWidth', 1.2);
    hold off;
end
hCbar.Layout.Tile = 'east'; %[output:4af059e3]
hCbar.Label.String = 'Relative Power (dB)'; %[output:4af059e3]
%%
%[text] ## Example 2: Resolution of two close sources
%[text] Two equally strong sources only 8 degrees apart in azimuth, imaged on a horizontal fan of directions. DAS barely separates them, MVDR and RCB show two clear peaks.
structSceneClose = structScene;
structSceneClose.sourceAzimuth = [-4 4];
structSceneClose.sourceElevation = [0 0];
structSceneClose.sourceStrength = [1 1];
dataClose = clait.simulatePassiveMicrophoneData(structSceneClose, structSensor);

structImage2D = structImage;
[structImage2D.directionsAzimuth, structImage2D.directionsElevation] = ...
    clait.generateDirections('2d', struct('spacing', 0.25, 'azimuthLimits', [-30 30]));

figure('Position', [100 100 800 420]); %[output:0985b155]
hold on; %[output:0985b155]
for cntMethod = 1:numel(methods)
    structImage2D.methodImaging = methods{cntMethod};
    power2D = clait.calculatePassiveAcousticImage(dataClose, structSensor, structImage2D);
    plot(structImage2D.directionsAzimuth, 10*log10(power2D / max(power2D)), 'LineWidth', 1.5, 'DisplayName', methods{cntMethod}); %[output:0985b155]
end
xline(structSceneClose.sourceAzimuth, 'k--', 'HandleVisibility', 'off'); %[output:0985b155]
hold off; %[output:0985b155]
grid on; box on; %[output:0985b155]
set(gca, 'XDir', 'reverse');   % positive azimuth on the left, as in the other plots %[output:0985b155]
ylim([-40 1]); %[output:0985b155]
xlabel('Azimuth (°)'); %[output:0985b155]
ylabel('Relative Power (dB)'); %[output:0985b155]
title('Two sources 8 degrees apart (dashed lines)'); %[output:0985b155]
legend('Location', 'southoutside', 'Orientation', 'horizontal'); %[output:0985b155]
%%
%[text] ## Example 3: Frequency content
%[text] The second and third outputs give the power per frequency bin. The DAS beam narrows with frequency, while MVDR resolves the two sources over most of the band.
figure('Position', [100 100 1100 420]); %[output:00fe7b3a]
tiledlayout(1, 2, 'TileSpacing', 'compact'); %[output:00fe7b3a]
for cntMethod = 1:2
    structImage2D.methodImaging = methods{cntMethod};
    [~, powerPerFrequency, frequencies] = clait.calculatePassiveAcousticImage(dataClose, structSensor, structImage2D);
    nexttile; %[output:00fe7b3a]
    imagesc(structImage2D.directionsAzimuth, frequencies / 1e3, 10*log10(powerPerFrequency ./ max(powerPerFrequency, [], 2)));
    set(gca, 'XDir', 'reverse', 'YDir', 'normal');
    clim([-30 0]);
    xlabel('Azimuth (°)');
    ylabel('Frequency (kHz)');
    title([methods{cntMethod} ', normalized per frequency']);
end
cb = colorbar; %[output:00fe7b3a]
cb.Layout.Tile = 'east'; %[output:00fe7b3a]
cb.Label.String = 'Relative Power (dB)'; %[output:00fe7b3a]

